def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    bg = grid[0][0]

    for r1 in range(rows):
        for c1 in range(cols):
            if grid[r1][c1] in (bg, 3):
                continue

            c_frame = grid[r1][c1]

            for r2 in range(r1 + 2, rows):
                # Check left border is all c_frame
                if not all(grid[i][c1] == c_frame for i in range(r1, r2 + 1)):
                    continue
                for c2 in range(c1 + 2, cols):
                    # Check right border is all c_frame
                    if not all(grid[i][c2] == c_frame for i in range(r1, r2 + 1)):
                        continue
                    # Check top border is all c_frame
                    if not all(grid[r1][k] == c_frame for k in range(c1, c2 + 1)):
                        continue
                    # Check bottom border is all c_frame
                    if not all(grid[r2][k] == c_frame for k in range(c1, c2 + 1)):
                        continue

                    # Check interior is all bg
                    interior_ok = True
                    for r in range(r1 + 1, r2):
                        for c in range(c1 + 1, c2):
                            if grid[r][c] != bg:
                                interior_ok = False
                                break
                        if not interior_ok:
                            break

                    if interior_ok:
                        for r in range(r1, r2 + 1):
                            for c in range(c1, c2 + 1):
                                if grid[r][c] == c_frame:
                                    grid[r][c] = 3
    return grid
